const fs = require('fs');
const path = '$TMPDIR/pg-eval-KWAeDz/upgrade/tracker.csv';
const text = fs.readFileSync(path, 'utf8');
const lines = text.trimEnd().split('\n');
const header = lines[0].split(',');
const idx = (name) => header.indexOf(name);

function parseLine(line) {
  const out = [];
  let cur = '', inQ = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (inQ) {
      if (c === '"' && line[i+1] === '"') { cur += '"'; i++; }
      else if (c === '"') inQ = false;
      else cur += c;
    } else {
      if (c === '"') inQ = true;
      else if (c === ',') { out.push(cur); cur = ''; }
      else cur += c;
    }
  }
  out.push(cur);
  return out;
}

function serializeRow(cols) {
  return cols.map(v => {
    if (/[",\n]/.test(v)) return '"' + v.replace(/"/g, '""') + '"';
    return v;
  }).join(',');
}

const rows = lines.slice(1).map(parseLine);
const today = '2026-11-04';

for (const row of rows) {
  if (row[idx('Owner role')] === 'Program owner' && row[idx('Owner')] === 'unknown') {
    row[idx('Owner')] = 'Jo Park';
  }
  const id = row[idx('ID')];
  if (id === 'B0-01') {
    row[idx('Status')] = 'Done';
    row[idx('Evidence')] = 'upgrade/results/bootstrap-code-search.txt';
    row[idx('Status since')] = today;
    row[idx('Notes')] = 'Code search via gh: no visible repos or hits; see Q-07.';
  }
  if (id === 'Q-07') {
    row[idx('Status')] = 'Waiting on customer';
    row[idx('Status since')] = today;
    row[idx('Notes')] = 'Bootstrap search found no repos (northwind-labs has no public repos; private repos not visible to agent). Need complete repo/service list and any off-GitHub consumers.';
  }
  if (id === 'Q-01') {
    row[idx('Notes')] = 'Draft from bootstrap: 45 minutes on a Sunday night (project.json). Business approval and named approver still needed.';
  }
  if (id === 'Q-10') {
    row[idx('Notes')] = 'When: Sunday night (no calendar date yet). Blackout dates unknown.';
  }
  if (id === 'D-03') {
    row[idx('Notes')] = 'Partial facts in project.json: 45 min, Sunday night; mode (read-write vs write-only) unknown.';
  }
  if (id === 'D-02') {
    row[idx('Notes')] = 'Target explicitly undecided at bootstrap.';
  }
}

const newRows = [
  {
    ID: 'Q-20', Type: 'Question', Block: '0', Stream: 'Discovery',
    Item: 'Who is the named DBA owner for nw-prod and this upgrade?',
    'Done when': 'DBA column set on all DBA-owned rows',
    'Owner role': 'Program owner', Owner: 'Jo Park', Side: 'Customer', 'Run by': 'Human',
    'Depends on': '', Gates: 'G0.2 G0.3 G0.4', Status: 'Not started', Notes: 'All DBA gate/task rows still have Owner=unknown.',
  },
  {
    ID: 'Q-21', Type: 'Question', Block: '0', Stream: 'Discovery',
    Item: 'What is the GCP project ID for Cloud SQL instance nw-prod?',
    'Done when': 'Project ID recorded in project.json or decision record',
    'Owner role': 'DBA', Owner: 'unknown', Side: 'Customer', 'Run by': 'Human',
    'Depends on': 'Q-20', Gates: 'G0.3', Status: 'Not started', Notes: '',
  },
  {
    ID: 'Q-22', Type: 'Question', Block: '0', Stream: 'Discovery',
    Item: 'Who is the business approver for the maintenance window and data-loss rule?',
    'Done when': 'Named person on Q-01 Q-03 D-03 D-04 and Business approver rows',
    'Owner role': 'Program owner', Owner: 'Jo Park', Side: 'Customer', 'Run by': 'Human',
    'Depends on': '', Gates: 'G0.6', Status: 'Not started', Notes: '',
  },
];

function blankRow() {
  return header.map(() => '');
}

for (const nr of newRows) {
  const row = blankRow();
  for (const [k, v] of Object.entries(nr)) {
    const i = idx(k);
    if (i >= 0) row[i] = v;
  }
  rows.push(row);
}

const out = [header.join(','), ...rows.map(serializeRow)].join('\n') + '\n';
fs.writeFileSync(path, out);
console.log('Updated', rows.length, 'rows');
NODE
